await page.setViewportSize({ width: 1440, height: 320 });
await page.addStyleTag({ content: '#diss-lab-tools {margin-bottom:360px!important;}' });
await capture(page).scrollIntoViewIfNeeded(); await expect(capture(page)).toBeInViewport();
await expect.poll(async () => source(page).evaluate((c: any) => { const box = c.getBoundingClientRect(); return box.bottom <= 0 || box.top >= window.innerHeight; })).toBe(true);
await expect.poll(async () => source(page).evaluate((c: any) => c._dissInViewport)).toBe(false);
const geometry = await page.evaluate(() => {
  const canvas = document.querySelector('[data-diss-canvas]')!, button = document.querySelector('[data-evidence-capture]')!;
  const box = (node: Element) => { const r = node.getBoundingClientRect(); return { top: r.top, bottom: r.bottom, width: r.width, height: r.height }; };
  return { viewportHeight: window.innerHeight, canvas: box(canvas), capture: box(button) };
});
expect(geometry.canvas.bottom <= 0 || geometry.canvas.top >= geometry.viewportHeight).toBe(true);
expect(geometry.capture.bottom).toBeGreaterThan(0); expect(geometry.capture.top).toBeLessThan(geometry.viewportHeight);

await preference(page).selectOption('canvas'); await capture(page).scrollIntoViewIfNeeded();
await expect.poll(async () => source(page).evaluate((c: any) => c._dissInViewport)).toBe(false);
const full = await nativeCapture(page), second = (await observations(page))[1];

